# Move full car-helicopter and Cessna audio kernels with plain camera/vector storage
import re
from audio_controls_migration import function
NAMES={'ProcessCarHeli':'Heli','ProcessCesna':'Cesna'}
CONSTANTS='\tCAR_HELI_MAX_DIST = 250,\n\tCAR_HELI_ENGINE_MAX_DIST = 140,\n\tCAR_HELI_ENGINE_START_MAX_DIST = 30,\n\tCAR_HELI_ENGINE_START_VOLUME = 70,\n\tCAR_HELI_SEAPLANE_MAX_DIST = 20,\n\tCAR_HELI_SEAPLANE_VOLUME = 100,\n\tCAR_HELI_REAR_MAX_DIST = 27,\n\tCAR_HELI_REAR_VOLUME = 25,\n\tCESNA_IDLE_MAX_DIST = 200,\n\tCESNA_REV_MAX_DIST = 90,\n\tCESNA_VOLUME = 80,\n'
HOST='//+ rouz edit (ChatGPT)\nextern "C" float\nAudioAircraftHost_MovingSpeed(const CVehicle *vehicle)\n{\n\t// Read the original captured rotor speed input\n\treturn ((const CBoat *)vehicle)->m_fMovingSpeed;\n}\nextern "C" float\nAudioAircraftHost_WheelSpeed(const CVehicle *vehicle)\n{\n\t// Read the original captured rotor speed input\n\treturn ((const CAutomobile *)vehicle)->m_aWheelSpeed[1];\n}\nextern "C" void\nAudioAircraftHost_Forward(CVehicle *vehicle, AudioSoundPosition *forward)\n{\n\t// Copy the live vehicle forward vector for the original dot product\n\t*forward = AudioSoundPosition_FromVector(vehicle->GetMatrix().GetForward());\n}\nextern "C" void\nAudioAircraftHost_Boot(CVehicle *vehicle, AudioSoundPosition *position)\n{\n\t// Resolve the original boot component on the captured automobile\n\tCVector point;\n\t((CAutomobile *)vehicle)->GetComponentWorldPosition(CAR_BOOT, point);\n\t*position = AudioSoundPosition_FromVector(point);\n}\nextern "C" void\nAudioAircraftHost_Matrix(CVehicle *vehicle, AudioCameraMatrix *matrix)\n{\n\t// Copy the original vehicle basis and translation for the rear rotor transform\n\tconst CMatrix &value = vehicle->GetMatrix();\n\tmatrix->rx = value.rx;\n\tmatrix->ry = value.ry;\n\tmatrix->rz = value.rz;\n\tmatrix->fx = value.fx;\n\tmatrix->fy = value.fy;\n\tmatrix->fz = value.fz;\n\tmatrix->ux = value.ux;\n\tmatrix->uy = value.uy;\n\tmatrix->uz = value.uz;\n\tmatrix->px = value.px;\n\tmatrix->py = value.py;\n\tmatrix->pz = value.pz;\n}\nextern "C" uint8_t\nAudioAircraftHost_FixedCamera(void)\n{\n\t// Query the active camera mode only at the original seaplane gate\n\treturn TheCamera.Cams[TheCamera.ActiveCam].Mode == CCam::MODE_FIXED;\n}\n//- rouz edit (ChatGPT)\n'
HELPERS='static float AudioAircraft_UpDot(const AudioCameraMatrix *matrix)\n{\n\t// Preserve all original dot-product terms including the zero multipliers\n\treturn matrix->ux * 0.0f + matrix->uy * 1.0f + matrix->uz * 0.0f;\n}\nstatic float AudioAircraft_ForwardDot(CVehicle *vehicle, const AudioCameraMatrix *matrix)\n{\n\t// Copy the live forward vector before applying the original dot product\n\tAudioSoundPosition forward;\n\tAudioAircraftHost_Forward(vehicle, &forward);\n\treturn forward.x * matrix->fx + forward.y * matrix->fy + forward.z * matrix->fz;\n}\nstatic void AudioAircraft_Rear(CVehicle *vehicle, AudioSoundPosition *position)\n{\n\t// Preserve the original complete matrix-vector product and vanilla discarded result\n\tAudioCameraMatrix matrix;\n\tAudioSoundPosition result;\n\tAudioAircraftHost_Matrix(vehicle, &matrix);\n\tresult.x = matrix.rx * 0.0f + matrix.fx * -10.0f + matrix.ux * 0.0f + matrix.px;\n\tresult.y = matrix.ry * 0.0f + matrix.fy * -10.0f + matrix.uy * 0.0f + matrix.py;\n\tresult.z = matrix.rz * 0.0f + matrix.fz * -10.0f + matrix.uz * 0.0f + matrix.pz;\n\tif (position) *position = result;\n}\n'
HOST+='#ifdef GTA_PS2\n//+ rouz edit (ChatGPT)\nextern "C" void\nAudioAircraftHost_CameraBegin(AudioCameraMatrix *matrix, void **attachment, uint8_t *owned)\n{\n\t// Preserve the original PS2 matrix assignment and transfer its cleanup state into C\n\tCMatrix copy;\n\tcopy = TheCamera.GetMatrix();\n\tmatrix->rx = copy.rx;\n\tmatrix->ry = copy.ry;\n\tmatrix->rz = copy.rz;\n\tmatrix->fx = copy.fx;\n\tmatrix->fy = copy.fy;\n\tmatrix->fz = copy.fz;\n\tmatrix->ux = copy.ux;\n\tmatrix->uy = copy.uy;\n\tmatrix->uz = copy.uz;\n\tmatrix->px = copy.px;\n\tmatrix->py = copy.py;\n\tmatrix->pz = copy.pz;\n\t*attachment = copy.m_attachment;\n\t*owned = copy.m_hasRwMatrix;\n\tcopy.m_attachment = nil;\n\tcopy.m_hasRwMatrix = false;\n}\nextern "C" void\nAudioAircraftHost_CameraEnd(void *attachment, uint8_t owned)\n{\n\t// Preserve the original PS2 matrix destructor condition at the generator return\n\tif (owned && attachment) RwMatrixDestroy((RwMatrix *)attachment);\n}\n//- rouz edit (ChatGPT)\n#endif\n'
PROTOTYPES='uint8_t AudioAircraft_Heli(cAudioManager *manager, cVehicleParams *params);\nvoid AudioAircraft_Cesna(cAudioManager *manager, cVehicleParams *params);\nfloat AudioAircraftHost_MovingSpeed(const CVehicle *vehicle);\nfloat AudioAircraftHost_WheelSpeed(const CVehicle *vehicle);\nvoid AudioAircraftHost_Forward(CVehicle *vehicle, AudioSoundPosition *forward);\nvoid AudioAircraftHost_Boot(CVehicle *vehicle, AudioSoundPosition *position);\nvoid AudioAircraftHost_Matrix(CVehicle *vehicle, AudioCameraMatrix *matrix);\nuint8_t AudioAircraftHost_FixedCamera(void);\n'

PROTOTYPES+='#ifdef GTA_PS2\nvoid AudioAircraftHost_CameraBegin(AudioCameraMatrix *matrix, void **attachment, uint8_t *owned);\nvoid AudioAircraftHost_CameraEnd(void *attachment, uint8_t owned);\n#endif\n'

def logic(source):
    # Remove both complete members and their private constants before updating every caller
    if 'cAudioManager::ProcessCarHeli(' in source and 'cAudioManager::ProcessCesna(' not in source:
        return source
    if 'cAudioManager::ProcessCarHeli(' in source:
        for name in NAMES:source=source.replace(function(source,'cAudioManager::',name)+'\n','')
        source+=HOST
    for line in CONSTANTS.splitlines():source=source.replace(line+'\n','')
    if HOST in source:source=source.replace(HOST,'')+HOST
    for name,target in NAMES.items():source=source.replace(name+'(params)','AudioAircraft_'+target+'(this, &params)')
    import audio_plane_migration
    return audio_plane_migration.logic(source)

def header(source):
    # Replace the owning member declarations with explicit C operations
    source='\n'.join(line for line in source.split('\n') if not any(re.search(r'\b'+name+r'\(',line) for name in NAMES))
    import audio_plane_migration
    return audio_plane_migration.header(source.replace('void AudioManager_InitState(cAudioManager *manager);',PROTOTYPES+'void AudioManager_InitState(cAudioManager *manager);'))

def body(source):
    # Preserve complete branches, shared frequency history and temporary rear-position bookkeeping
    source=source[source.index('{'):]
    source=re.sub(r'(?<![.>\w])\b(m_\w+)\b',r'manager->\1',source).replace('params.','params->')
    source=source.replace('CAutomobile* automobile','CVehicle* automobile').replace('CBoat* boat','CVehicle* boat').replace('(CAutomobile*)params->m_pVehicle','params->m_pVehicle').replace('(CBoat*)params->m_pVehicle','params->m_pVehicle').replace('CMatrix cameraMatrix','AudioCameraMatrix cameraMatrix').replace('CVector vecPosOld','AudioSoundPosition vecPosOld').replace('CVector backPropellerPos','AudioSoundPosition backPropellerPos')
    for a,b in [('FindPlayerVehicle()','AudioPoliceHost_PlayerVehicle()'),('Pads[0].GetAccelerate()','AudioVehicleModelHost_Accelerate()'),('Pads[0].GetBrake()','AudioVehicleModelHost_Brake()'),('params->m_pVehicle->m_fGasPedal','AudioVehicleReverseHost_Gas(params->m_pVehicle)'),('params->m_pVehicle->m_fBrakePedal','AudioVehicleModelHost_BrakePedal(params->m_pVehicle)'),('cameraMatrix = TheCamera.GetMatrix()','AudioGeometryHost_CameraMatrix(&cameraMatrix)'),('DotProduct(cameraMatrix.GetUp(), CVector(0.0f, 1.0f, 0.0f))','AudioAircraft_UpDot(&cameraMatrix)'),('DotProduct(params->m_pVehicle->GetMatrix().GetForward(), cameraMatrix.GetForward())','AudioAircraft_ForwardDot(params->m_pVehicle, &cameraMatrix)'),('params->m_pVehicle->GetModelIndex()','AudioVehicleReverseHost_Model(params->m_pVehicle)'),('boat->m_fMovingSpeed','AudioAircraftHost_MovingSpeed(boat)'),('automobile->m_aWheelSpeed[1]','AudioAircraftHost_WheelSpeed(automobile)'),('automobile->GetComponentWorldPosition(CAR_BOOT, backPropellerPos)','AudioAircraftHost_Boot(automobile, &backPropellerPos)'),('automobile->bEngineOn','AudioVehicleReverseHost_Engine(automobile)'),('TheCamera.Cams[TheCamera.ActiveCam].Mode == CCam::MODE_FIXED','AudioAircraftHost_FixedCamera()')]:source=source.replace(a,b)
    source=source.replace('#ifdef FIX_BUGS\n\t\t\tbackPropellerPos = \n#endif\n\t\t\tparams->m_pVehicle->GetMatrix() * CVector(0.0f, -10.0f, 0.0f);','#ifdef FIX_BUGS\n\t\t\tAudioAircraft_Rear(params->m_pVehicle, &backPropellerPos);\n#else\n\t\t\tAudioAircraft_Rear(params->m_pVehicle, NULL);\n#endif')
    source=source.replace('AudioSoundPosition_ToVector(&manager->m_sQueueSample.m_vecPos)','manager->m_sQueueSample.m_vecPos').replace('AudioSoundPosition_FromVector(backPropellerPos)','backPropellerPos').replace('AudioSoundPosition_FromVector(vecPosOld)','vecPosOld')
    for a,b in [('uint32','uint32_t'),('uint8','uint8_t'),('int16','int16_t'),('bool8','uint8_t'),('TRUE','1'),('FALSE','0'),('nil','NULL'),('Min','AUDIO_AIRCRAFT_MIN'),('Max','AUDIO_AIRCRAFT_MAX'),('Clamp2','AUDIO_AIRCRAFT_CLAMP'),('ABS','AUDIO_AIRCRAFT_ABS')]:source=re.sub(r'\b'+a+r'\b',b,source)
    for name in ['CAR_HELI_MAX_DIST','CAR_HELI_ENGINE_MAX_DIST','CAR_HELI_REAR_MAX_DIST','CESNA_IDLE_MAX_DIST','CESNA_REV_MAX_DIST']:source=source.replace('SQR('+name+')','('+name+' * '+name+')')
    source=source.replace('AudioRequests_Submit(this)','AudioRequests_Submit(manager)')
    for name in ['SET_EMITTING_VOLUME','RESET_LOOP_OFFSETS','SET_LOOP_OFFSETS','SET_SOUND_REVERB','SET_SOUND_REFLECTION']:source=re.sub(r'\b'+name+r'\b','AUDIO_AIRCRAFT_'+name,source)
    if 'AudioCameraMatrix cameraMatrix;' in source:
        source=source.replace('AudioCameraMatrix cameraMatrix;', 'AudioCameraMatrix cameraMatrix;\n#ifdef GTA_PS2\n    // Store the original matrix assignment cleanup state until this generator returns\n    void *cameraAttachment = NULL;\n    uint8_t cameraOwned = 0;\n#endif')
        source=source.replace('AudioGeometryHost_CameraMatrix(&cameraMatrix);', '#ifdef GTA_PS2\n    AudioAircraftHost_CameraBegin(&cameraMatrix, &cameraAttachment, &cameraOwned);\n#else\n    AudioGeometryHost_CameraMatrix(&cameraMatrix);\n#endif')
        source=re.sub(r'\breturn ([01]);', r'{\n    // Complete the original camera snapshot lifecycle before returning\n#ifdef GTA_PS2\n    AudioAircraftHost_CameraEnd(cameraAttachment, cameraOwned);\n#endif\n    return \1;\n}', source)
    return source
